  if (!/^\d{4}-\d{2}-\d{2}$/.test(entry.date ?? '') || Number.isNaN(Date.parse(`${entry.date}T00:00:00Z`))) problems.push(`date "${entry.date}" is not a YYYY-MM-DD date`);
